      homeQuick: "Быстрые ссылки",
      qServices: "e-Irad: очередь на паспорт, разрешения, счета и отслеживание посылок",
      qAddr: "Обращения губернатора", qHol: "Праздничные дни", qAdmin: "Министерства, департаменты и ведомства",
